<?php
declare(strict_types=1);
require_once __DIR__ . '/config/database.php';
require_once __DIR__ . '/includes/functions.php';
require_patient();
$patient = current_patient();
$patientId = (int)$patient['patient_id'];
$stmt = $pdo->prepare('SELECT p.*,d.name AS department_name,doc.name AS doctor_name FROM patients p LEFT JOIN departments d ON d.id=p.department_id LEFT JOIN doctors doc ON doc.id=p.doctor_id WHERE p.id=? LIMIT 1');
$stmt->execute([$patientId]);
$record = $stmt->fetch();
if (!$record) { unset($_SESSION['patient']); redirect('patient_login.php'); }
$appointments = $pdo->prepare('SELECT a.appointment_date,a.appointment_time,a.reason,a.token_number,a.status,doc.name AS doctor_name,dep.name AS department_name FROM appointments a LEFT JOIN doctors doc ON doc.id=a.doctor_id LEFT JOIN departments dep ON dep.id=a.department_id WHERE a.patient_id=? ORDER BY a.appointment_date DESC,a.appointment_time DESC LIMIT 8');
$appointments->execute([$patientId]);
$appointmentRows = $appointments->fetchAll();
$bills = $pdo->prepare('SELECT bill_code,bill_date,category,total_amount,paid_amount,balance,status FROM bills WHERE patient_id=? ORDER BY bill_date DESC,id DESC LIMIT 6');
$bills->execute([$patientId]);
$billRows = $bills->fetchAll();
$prescriptions = $pdo->prepare('SELECT pr.prescription_code,pr.prescribed_at,pr.diagnosis,pr.instructions,doc.name AS doctor_name FROM prescriptions pr LEFT JOIN doctors doc ON doc.id=pr.doctor_id WHERE pr.patient_id=? ORDER BY pr.prescribed_at DESC LIMIT 5');
$prescriptions->execute([$patientId]);
$prescriptionRows = $prescriptions->fetchAll();
$flashes = consume_flashes();
?>
