<div class="row g-3 mb-4"><div class="col-md-4"><div class="portal-stat"><span class="portal-stat-icon blue"><i class="fa-solid fa-calendar-check"></i></span><div><small>Appointments</small><strong><?= count($appointmentRows) ?></strong></div></div></div><div class="col-md-4"><div class="portal-stat"><span class="portal-stat-icon teal"><i class="fa-solid fa-file-invoice"></i></span><div><small>Recent bills</small><strong><?= count($billRows) ?></strong></div></div></div><div class="col-md-4"><div class="portal-stat"><span class="portal-stat-icon violet"><i class="fa-solid fa-file-prescription"></i></span><div><small>Prescriptions</small><strong><?= count($prescriptionRows) ?></strong></div></div></div></div>
<div class="row g-4"><div class="col-lg-7"><section class="portal-panel"><div class="panel-title"><div><span class="section-kicker">YOUR VISITS</span><h2>Appointments</h2></div><span class="panel-title-icon"><i class="fa-solid fa-calendar-days"></i></span></div><?php if (!$appointmentRows): ?><p class="empty-note">No appointments are linked to your account yet. Please contact reception to book a visit.</p><?php else: ?><div class="table-responsive"><table class="table portal-table"><thead><tr><th>Date & time</th><th>Doctor</th><th>Status</th></tr></thead><tbody><?php foreach ($appointmentRows as $a): ?><tr><td><?= e(date('d M Y',strtotime($a['appointment_date']))) ?><small><?= e(substr((string)$a['appointment_time'],0,5)) ?></small></td><td><?= e($a['doctor_name'] ?: 'Not assigned') ?><small><?= e($a['department_name'] ?: '') ?></small></td><td><span class="portal-status"><?= e($a['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="portal-panel mt-4"><div class="panel-title"><div><span class="section-kicker">MEDICAL INFORMATION</span><h2>Prescriptions</h2></div><span class="panel-title-icon"><i class="fa-solid fa-prescription"></i></span></div><?php if (!$prescriptionRows): ?><p class="empty-note">No prescriptions are available in your portal yet.</p><?php else: ?><?php foreach ($prescriptionRows as $pr): ?><div class="prescription-row"><div><b><?= e($pr['prescription_code']) ?> · <?= e($pr['diagnosis']) ?></b><small><?= e($pr['doctor_name'] ?: 'Hospital doctor') ?> · <?= e(date('d M Y',strtotime($pr['prescribed_at']))) ?></small><?php if ($pr['instructions']): ?><p><?= e($pr['instructions']) ?></p><?php endif; ?></div></div><?php endforeach; ?><?php endif; ?></section></div>
<div class="col-lg-5"><section class="portal-panel"><div class="panel-title"><div><span class="section-kicker">ACCOUNT DETAILS</span><h2>My profile</h2></div><span class="panel-title-icon"><i class="fa-solid fa-user"></i></span></div><div class="profile-line"><small>Full name</small><b><?= e($record['name']) ?></b></div><div class="profile-line"><small>Email</small><b><?= e($record['email']) ?></b></div><div class="profile-line"><small>Mobile</small><b><?= e($record['phone']) ?></b></div><div class="profile-line"><small>Gender / Age</small><b><?= e($record['gender'] ?: '—') ?><?= $record['age'] !== null ? ' / ' . e($record['age']) : '' ?></b></div><div class="profile-line"><small>Blood group</small><b><?= e($record['blood_group'] ?: 'Unknown') ?></b></div><div class="profile-line"><small>Department</small><b><?= e($record['department_name'] ?: 'Not assigned') ?></b></div><div class="profile-line"><small>Address</small><b><?= e($record['address'] ?: '—') ?></b></div><p class="portal-help">To update medical details or contact information, please contact hospital reception so your identity can be verified.</p></section>
<section class="portal-panel mt-4"><div class="panel-title"><div><span class="section-kicker">PAYMENTS</span><h2>Recent bills</h2></div><span class="panel-title-icon"><i class="fa-solid fa-receipt"></i></span></div><?php if (!$billRows): ?><p class="empty-note">No billing records are available yet.</p><?php else: ?><?php foreach ($billRows as $bill): ?><div class="bill-row"><div><b><?= e($bill['bill_code']) ?></b><small><?= e(date('d M Y',strtotime($bill['bill_date']))) ?> · <?= e($bill['category']) ?></small></div><div class="text-end"><b>₹<?= number_format((float)$bill['total_amount'],2) ?></b><small><?= e($bill['status']) ?> · Due ₹<?= number_format((float)$bill['balance'],2) ?></small></div></div><?php endforeach; ?><?php endif; ?></section></div></div>
